public function testFixPhp74(string $expected, ?string $input = null, array $configuration = []): void
{
    $this->fixer->configure($configuration);

    $this->doTest($expected, $input);
}

public static function provideFixPhp74Cases(): iterable
{
    yield [
        '<?php
