            '<?php
            class Foo
            {
                private bool|int | string $prop;
                public function bar(TypeA | TypeB|TypeC $x): TypeA|TypeB | TypeC|TypeD
                {
                }
                public function baz(
                    callable|array $a,
                    array|callable $b,
                ) {}
                public function qux(
